import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.CxkNbRKf.js";const c=JSON.parse('{"title":"Upgrade from 4.2 to 4.3","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/upgrade/upgrade-43.md","filePath":"installation-guide/upgrade/upgrade-43.md","lastUpdated":1786379412000}'),o={name:"installation-guide/upgrade/upgrade-43.md"};function h(p,e,l,n,r,d){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="upgrade-from-4-2-to-4-3" tabindex="-1">Upgrade from 4.2 to 4.3 <a class="header-anchor" href="#upgrade-from-4-2-to-4-3" aria-label="Permalink to &quot;Upgrade from 4.2 to 4.3&quot;">​</a></h1><p>The upgrade includes changes to the theme and will not work with your existing NADA 4.2 theme.</p><h2 id="_1-apply-patch-to-upgrade" tabindex="-1">1. Apply patch to upgrade <a class="header-anchor" href="#_1-apply-patch-to-upgrade" aria-label="Permalink to &quot;1. Apply patch to upgrade&quot;">​</a></h2><p>a. Make a backup of your existing NADA folders. If complete backup is not possible, at least backup the &quot;Application&quot; and &quot;Themes&quot; folder b. Download the patch zip file: <a href="http://ihsn.org/download/nada42-to-43-update.zip" target="_blank" rel="noreferrer">http://ihsn.org/download/nada42-to-43-update.zip</a> c. Unzip the patch files in the NADA root folder to replace existing files d. Run this query on the database to add the new &quot;Open data&quot; access type</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INSERT INTO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> forms </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Open access&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;open&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;open&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="_2-update-theme-template" tabindex="-1">2. Update Theme/template <a class="header-anchor" href="#_2-update-theme-template" aria-label="Permalink to &quot;2. Update Theme/template&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Important</p><p>The default theme has changed in NADA. This is a major change and will break your existing website layout/theme. To upgrade you theme, please follow the steps below:</p></div><h2 id="_2-1-website-using-the-default-theme-wb" tabindex="-1">2.1. Website using the default theme &quot;WB&quot;: <a class="header-anchor" href="#_2-1-website-using-the-default-theme-wb" aria-label="Permalink to &quot;2.1. Website using the default theme &quot;WB&quot;:&quot;">​</a></h2><p>Edit the <strong>application/config/template.php</strong> and change the default theme name to <strong>&quot;wb2&quot;</strong> instead of <strong>&quot;wb&quot;</strong></p><h2 id="_2-2-websites-with-heavily-customized-theme" tabindex="-1">2.2. Websites with heavily customized theme <a class="header-anchor" href="#_2-2-websites-with-heavily-customized-theme" aria-label="Permalink to &quot;2.2. Websites with heavily customized theme&quot;">​</a></h2><p>a. Backup your theme folder b. Make a copy of the <strong>themes/wb2</strong> folder to create a new theme folder c. Apply all the customizations (header, footer, styles, etc) to your copy of the <strong>wb2 theme</strong>. d. Update the <strong>application/config/template</strong> to use your new theme.</p>',11)])])}const g=t(o,[["render",h]]);export{c as __pageData,g as default};
